 void PickBan(int slot)
 {
  while(Session.Map!=null)
  {
   var map=Session.Map;var grid=new UniformGrid{Columns=11};var panel=new DockPanel{Margin=new Thickness(16)};var search=new TextBox{Margin=new Thickness(0,0,0,15)};DockPanel.SetDock(search,Dock.Top);panel.Children.Add(search);panel.Children.Add(grid);var dialog=Dialog(Session.Current.Team(MapRecord.BanTeam(slot))+" · "+map.BanRole(slot),panel,1100,470);string? chosen=null;
   void Fill(){grid.Children.Clear();foreach(var op in OperatorOrder.Sort(Session.Catalog.Operators,map.BanRole(slot)).Where(o=>o.Name.Contains(search.Text,StringComparison.OrdinalIgnoreCase))){var button=Ui.Button("",()=>{chosen=op.Id;dialog.DialogResult=true;});button.Margin=new Thickness(3);button.Padding=new Thickness(4);var stack=new StackPanel();try{stack.Children.Add(new Image{Source=Ui.FileImage(SiegeCatalog.Asset(op.Icon)),Height=43,Stretch=Stretch.Uniform});}catch{}stack.Children.Add(new TextBlock{Text=op.Name,FontSize=10,TextAlignment=TextAlignment.Center,TextWrapping=TextWrapping.Wrap});button.Content=stack;button.ToolTip=op.Name;button.IsEnabled=!Enumerable.Range(slot/6*6,6).Any(i=>i!=slot&&map.Bans[i]==op.Id);grid.Children.Add(button);}}search.TextChanged+=(_,_)=>Fill();Fill();if(dialog.ShowDialog()!=true||chosen==null)return;Session.Ban(slot,chosen);var pending=Session.PendingBans();if(pending.Length==0)return;slot=pending[0];
  }
 }
 void EditRound(int index)
 {
  var map=Session.Map!;if(map.Confirmed)throw new InvalidOperationException(L.T("Mapa confirmado. Abra uma revisão para corrigir os dados."));var panel=new StackPanel{Margin=new Thickness(20)};var sites=Ui.Combo();sites.ItemsSource=Session.Catalog.Maps.Single(m=>m.Id==map.MapId).Sites.Select(s=>new MapChoice(s,BombsiteNames.Display(map.MapId,s))).ToList();sites.SelectedIndex=Array.IndexOf(Session.Catalog.Maps.Single(m=>m.Id==map.MapId).Sites,map.Rounds[index].Site);var teams=Ui.Combo(Session.Current.TeamA,Session.Current.TeamB);teams.SelectedIndex=map.Rounds[index].Winner;var ends=Ui.Combo();ends.ItemsSource=RoundEnding.Codes.Select(c=>new MapChoice(c,RoundEnding.Label(c))).ToList();ends.SelectedIndex=Array.IndexOf(RoundEnding.Codes,map.Rounds[index].Ending);panel.Children.Add(sites);panel.Children.Add(teams);panel.Children.Add(ends);var trim=new CheckBox{Content=L.T("Permitir remover rounds posteriores se o mapa terminar antes"),Margin=new Thickness(5)};panel.Children.Add(trim);var dialog=Dialog(L.T("Corrigir round"),panel,580,340);panel.Children.Add(Ui.Button("Confirmar",()=>{try{Session.Round((sites.SelectedItem as MapChoice)?.Id??"",teams.SelectedIndex,(ends.SelectedItem as MapChoice)?.Id??"",index,trim.IsChecked==true);dialog.DialogResult=true;}catch(Exception ex){MessageBox.Show(dialog,ex.Message);}},true));dialog.ShowDialog();
 }
 void Review(){var panel=new StackPanel{Margin=new Thickness(20)};panel.Children.Add(Ui.Text("Informe o motivo da revisão. O resultado anterior será preservado no histórico da partida."));var reason=new TextBox();panel.Children.Add(reason);var dialog=Dialog(L.T("Revisar resultado"),panel,600,300);panel.Children.Add(Ui.Button("Abrir revisão",()=>{try{Session.Review(reason.Text);dialog.DialogResult=true;}catch(Exception ex){MessageBox.Show(dialog,ex.Message);}},true));dialog.ShowDialog();}
 void Logo(int team){var dialog=new OpenFileDialog{Filter=L.T("Imagem PNG ou JPEG|*.png;*.jpg;*.jpeg")};if(dialog.ShowDialog(Window.GetWindow(this))!=true)return;var brand=MatchFiles.ReadBrand(Session.Current);string path=MatchFiles.Resource(Session.Current,team==0?"logo-a":"logo-b",dialog.FileName);if(team==0)brand.TeamALogo=path;else brand.TeamBLogo=path;MatchFiles.SaveBrand(Session.Current,brand);}
