 async System.Threading.Tasks.Task Package(bool export){try{FlushNames();string path;if(export){var dialog=new SaveFileDialog{Filter="Pacote CasterDesk|*.casterdesk",FileName=MatchStore.ExportFileName(Session.Current).Replace(".json",".casterdesk")};if(dialog.ShowDialog(Window.GetWindow(this))!=true)return;path=dialog.FileName;}else{var dialog=new OpenFileDialog{Filter="Pacote CasterDesk|*.casterdesk"};if(dialog.ShowDialog(Window.GetWindow(this))!=true)return;path=dialog.FileName;}Processing=true;IsEnabled=false;notice.Text=L.T("Processando pacote da partida…");var match=Session.Current;var existing=Session.Matches.ToArray();if(export)await System.Threading.Tasks.Task.Run(()=>MatchPackage.Export(match,path));else{var imported=await System.Threading.Tasks.Task.Run(()=>MatchPackage.Import(path,Session.Catalog,existing));Session.AttachImported(imported);}notice.Text=L.T("Pacote concluído.");}catch(Exception ex){notice.Text=ex.Message;}finally{Processing=false;IsEnabled=true;}}
